(async () => {
 'use strict';
 const currentUser=await MGTU_adminReady;if(!currentUser)return;
 const isAdmin=()=>currentUser.role==='admin';
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=MGTU_escape;
 let draft=structuredClone(MGTU_content()),data={programs:[],facts:[]},view='page',dirty=false,previewMode=window.innerWidth<=760?'mobile':'desktop';
 const labels={users:['Пользователи','Кто работает с сайтом.','Добавляйте пользователей, назначайте роли и управляйте доступом.'],account:['Мой аккаунт','Ваш доступ к редактору.','Управляйте паролем своей учётной записи.'],page:['Блоки страницы','Выберите блок. Меняйте наглядно.','Нажмите элемент в предпросмотре или выберите его в списке. Все настройки ниже относятся только к нему.'],programs:['Направления','Направления под контролем.','Редактируйте описания и оформление. Условия приёма обновляются с abit.mkgtu.ru.'],design:['Оформление','Характер вашего университета.','Настройте фирменные цвета и шрифт без правки кода.'],applications:['Заявки','От интереса — к встрече.','Регистрации на мероприятие, контакты участников и доставка уведомлений.']};
 const input=(label,key,value,options={})=>`<label>${esc(label)}${options.textarea?`<textarea data-field="${key}" rows="${options.rows||3}">${esc(value)}</textarea>`:`<input data-field="${key}" type="${options.type||'text'}" value="${esc(value)}" ${options.maxlength?'maxlength="'+options.maxlength+'"':''}>`}${options.hint?`<small>${esc(options.hint)}</small>`:''}</label>`;
 const toggle=(label,key,value)=>`<label class="toggle-field">${esc(label)}<input type="checkbox" data-field="${key}" ${value?'checked':''}></label>`;
 let previewTimer;
 function setDirty(value=true){dirty=value;if(value){clearTimeout(previewTimer);previewTimer=setTimeout(()=>MGTU_editor.preview(),140);}$('#draftState').textContent=dirty?'Есть несохранённые изменения':'Все изменения сохранены';$('#draftState').style.color=dirty?'#9a7729':'';}
 function render(){if(!isAdmin()&&['users','design','applications'].includes(view))view='page';const management=['users','account','applications'].includes(view);document.querySelector('.admin-main').classList.toggle('management-mode',management);$('#saveDraft').hidden=management;$('#resetDraft').hidden=management;$('.preview-switch').hidden=management;const info=labels[view];$('#viewBreadcrumb').textContent=info[0];$('#viewTitle').textContent=info[1];$('#viewDescription').textContent=info[2];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  if(view==='users')MGTU_users.render();if(view==='account')$('#editorPanel').innerHTML=MGTU_users.account();
  if(view==='page')$('#editorPanel').innerHTML=MGTU_editor.render();
  if(view==='programs'){$('#editorPanel').innerHTML='<input class="admin-search" id="adminSearch" type="search" aria-label="Поиск программ в редакторе" placeholder="Найти программу или факультет"><p class="program-editor-count">'+data.programs.length+' программ из исходного каталога</p><div id="adminPrograms"></div>';renderProgramList('');$('#adminSearch').addEventListener('input',e=>renderProgramList(e.target.value));}
  if(view==='design')$('#editorPanel').innerHTML='<div class="editor-card"><span class="admin-badge">МГТУ / ПАЛИТРА 02</span><h2>Один вуз. Разные характеры.</h2><p>Основная концепция — глубокий синий, холодный голубой и лавандовый. Направления используют тематические палитры.</p><div class="editor-fields">'+color('Светлый акцент','accent',draft.accent)+color('Голубой акцент','secondary',draft.secondary)+color('Основной тёмный','background',draft.background)+'</div></div><div class="editor-card"><h2>Палитры направлений</h2><p>Нажмите палитру, чтобы попробовать её как основную тему макета. Цвета карточек направлений сохранят свою принадлежность.</p><div class="palette-library">'+Object.entries(MGTU_PALETTES).map(([key,p])=>'<button class="palette-option" data-palette="'+key+'"><span>'+esc(p.name)+'</span><span>'+p.colors.map(c=>'<i style="--swatch:'+c+'" title="'+c+'"></i>').join('')+'</span></button>').join('')+'</div><p class="editor-palette-note">Янтарный #FFB020 сохранён в фирменной палитре как вариант для обсуждения.</p></div><div class="editor-card"><h2>Типографика</h2><div class="font-specimen">Steppe.<br>День открытых дверей в МГТУ.</div><p>Подключены пять начертаний Steppe: Regular, Medium, SemiBold, Bold и ExtraBold. Файлы находятся в самом макете.</p><div class="editor-fields">'+'<label>Шрифт по умолчанию для страницы<select data-field="font">'+MGTU_EDITOR_FONTS.map(name=>'<option '+(draft.font===name?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select><small>Для отдельного заголовка или кнопки используйте «Блоки страницы».</small></label>'+'</div></div><div class="editor-card"><h2>Логотип</h2><div class="admin-logo-sample"><img src="assets/logo-white.png" alt="Логотип МГТУ" width="220" height="25"></div><p>Официальный логотип МГТУ из брендбука. Белая версия используется на тёмном фоне.</p></div>';
  if(view==='applications')MGTU_applications.render();
 }
 function color(label,key,value){return `<label>${esc(label)}<div class="color-row"><input type="color" data-color="${key}" value="${esc(value)}" aria-label="${esc(label)}: выбор цвета"><input type="text" data-field="${key}" value="${esc(value)}" pattern="#[0-9a-fA-F]{6}" maxlength="7" aria-label="${esc(label)}: HEX"></div></label>`;}
 function editableProgram(id){
  const original=data.programs.find(p=>p.id===id);if(!original)return null;
  const patch=draft.programs[id]||{};
  draft.programs[id]={...structuredClone(original),...patch,admission:{...structuredClone(original.admission||{}),...patch.admission}};
  return draft.programs[id];
 }
 function admissionTable(id,a){return `<div class="admission-editor"><h4>Места, формы обучения и квоты</h4><p>Меняйте каждую ячейку. Тире означает отсутствие мест.</p>${isAdmin()?input('Заголовки столбцов','programs.'+id+'.admission.columnsText',(a.headers||[]).join('\n'),{textarea:true,rows:3,hint:'Один столбец на строку. Можно добавить профиль или подразделение.'}):(a.headers||[]).map((h,i)=>input('Заголовок столбца '+(i+1),'programs.'+id+'.admission.headers.'+i,h)).join('')}<div class="admin-table-scroll"><table class="admin-admission-table"><thead><tr>${(a.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}<th></th></tr></thead><tbody>${(a.rows||[]).map((row,r)=>`<tr>${(a.headers||[]).map((h,c)=>`<td><input aria-label="${esc(h)}: строка ${r+1}" data-field="programs.${id}.admission.rows.${r}.${c}" value="${esc(row[c]||'')}"></td>`).join('')}<td><button class="remove-admission-row" data-remove-row="${r}" data-program="${id}" aria-label="Удалить строку ${r+1}">×</button></td></tr>`).join('')}</tbody></table></div><button class="admin-row-button" data-add-row="${id}">+ Добавить строку</button></div>`;}
 function applyRoleUI(){if(isAdmin())return;$('#editorPanel').querySelectorAll('[data-field],[data-color]').forEach(node=>{if(!MGTU_canEditPath(node.dataset.field||node.dataset.color))node.closest('label')?.setAttribute('hidden','');});$('#editorPanel').querySelectorAll('[data-program-style],[data-add-row],[data-remove-row],[data-reset-program]').forEach(node=>node.hidden=true);}
 function renderProgramList(query){const list=data.programs.filter(p=>{const s={...p,...draft.programs[p.id]};return(s.name+' '+s.faculty).toLowerCase().includes(query.trim().toLowerCase());});$('#adminPrograms').innerHTML=sourceStatus()+list.map(p=>{const s={...p,...draft.programs[p.id]},a=s.admission||{},key='programs.'+p.id+'.';return `<details class="program-editor-row" data-editor-program="${p.id}"><summary><span>${esc(s.name)}<br><small>${esc(s.level)}${a.code?' · '+esc(a.code):''}</small></span><span>⌄</span></summary><div class="editor-fields"><button class="admin-row-button" data-program-style="${p.id}">Оформление этой карточки на странице</button>${input('Название',key+'name',s.name)}${input('Факультет',key+'faculty',s.faculty)}${input('Краткое описание специальности',key+'description',s.description||'',{textarea:true,rows:4,hint:'Показывается в подробной карточке перед местами и формами обучения. До 1500 символов.'})}<label>Уровень образования<select data-field="${key}level">${['Бакалавриат','Специалитет','Магистратура'].map(level=>`<option ${s.level===level?'selected':''}>${level}</option>`).join('')}</select></label>${toggle('Показывать на сайте',key+'visible',s.visible!==false)}<div class="admission-editor"><h4>Условия приёма · abit.mkgtu.ru</h4><p>Баллы, места, профиль и сроки загружаются автоматически. Ручное редактирование отключено.</p><p>${esc(a.code||'')} · ${esc(a.year||'')}</p><p>${esc(a.status||'')}</p><p>${esc(a.profile||'')}</p><div class="admission-text">${esc((a.rows||[]).map(row=>row.join(': ')).join('\n'))}<br>${esc(a.ege||'Баллы в источнике не указаны.')}<br>${esc(a.duration||'Сроки в источнике не указаны.')}</div><a href="${esc(s.admissionSource?.url||'https://abit.mkgtu.ru/programs')}" target="_blank" rel="noopener">Открыть источник ↗</a></div></div></details>`;}).join('')||'<div class="editor-card"><p>Ничего не найдено. Попробуйте другое слово.</p></div>';applyRoleUI();}
 function sourceStatus(){const state=window.MGTU_admissionsSync;return `<div class="editor-card"><h3>Данные приёмной комиссии</h3><p>${state?.syncedAt?'Обновлено: '+new Date(state.syncedAt).toLocaleString('ru-RU'):'Первое обновление ещё не выполнено.'}</p>${state?.error?'<p>Источник временно недоступен. Сохранены последние успешно загруженные сведения.</p>':''}<p>Автообновление каждые 6 часов. Найдено направлений: ${state?.matched||0}.</p>${isAdmin()?'<button class="admin-row-button" id="syncAdmissions" type="button">Обновить из источника</button>':''}</div>`;}
 function refreshProgramEditor(id){const query=$('#adminSearch')?.value||'';renderProgramList(query);const row=$(`[data-editor-program="${id}"]`);if(row)row.open=true;}
 $('#editorPanel').addEventListener('click',e=>{
  if(e.target.closest('#syncAdmissions')){if(dirty){notify('Сначала сохраните или отмените правки.');return;}const button=e.target.closest('button');button.disabled=true;MGTU_api('/api/admissions-sync',{method:'POST'}).then(async state=>{const saved=await MGTU_api('/api/content');MGTU_setPublished(saved);draft=structuredClone(MGTU_content());renderProgramList($('#adminSearch')?.value||'');notify(state.error?'Не удалось обновить источник. Используется сохранённая копия.':'Условия приёма обновлены.');}).catch(error=>notify(error.message)).finally(()=>button.disabled=false);return;}
  if(e.target.closest('#importLocalDraft')&&isAdmin()){const old=MGTU_read('mgtu-content',null);if(!old)return;const merged={...MGTU_content(),...old};merged.programs={...MGTU_content().programs};for(const [id,patch] of Object.entries(old.programs||{})){const original=merged.programs[id];if(original)merged.programs[id]={...original,...patch,admission:{...original.admission,...patch.admission}};}merged.blocks=old.blocks||{};draft=merged;view='page';render();setDirty();MGTU_editor.preview();notify('Локальный черновик открыт. Проверьте его перед сохранением на сайте.');return;}
  const styleButton=e.target.closest('[data-program-style]');if(styleButton){if(!isAdmin())return;view='page';MGTU_editor.showProgram(styleButton.dataset.programStyle);return;}
  const add=e.target.closest('[data-add-row]'),remove=e.target.closest('[data-remove-row]'),reset=e.target.closest('[data-reset-program]');
  if((add||remove||reset)&&!isAdmin())return;
  if(add){const id=add.dataset.addRow,p=editableProgram(id);if(!p.admission.headers?.length)p.admission.headers=['Форма обучения','Бюджет','Отдельная квота','Особая квота','По договору'];p.admission.rows??=[];p.admission.rows.push(p.admission.headers.map(()=>''));setDirty();refreshProgramEditor(id);}
  if(remove){const id=remove.dataset.program,p=editableProgram(id);p.admission.rows.splice(Number(remove.dataset.removeRow),1);setDirty();refreshProgramEditor(id);}
  if(reset){const id=reset.dataset.resetProgram;delete draft.programs[id];setDirty();refreshProgramEditor(id);}
 });
 $('#editorPanel').addEventListener('change',e=>{if(!isAdmin()||!e.target.dataset.field?.endsWith('.columnsText'))return;const id=e.target.dataset.field.split('.')[1],p=editableProgram(id);p.admission.headers=e.target.value.split('\n').map(x=>x.trim()).filter(Boolean);p.admission.rows=(p.admission.rows||[]).map(row=>p.admission.headers.map((_,i)=>row[i]||''));delete p.admission.columnsText;setDirty();refreshProgramEditor(id);});
 $('#editorPanel').addEventListener('input',e=>{const key=e.target.dataset.field||e.target.dataset.color;if(!key||!MGTU_canEditPath(key))return;if(key.startsWith('programs.'))editableProgram(key.split('.')[1]);let value=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='factsText')draft.facts=value.split('\n').map(s=>s.trim()).filter(Boolean);else{const bits=key.split('.');let target=draft;for(const part of bits.slice(0,-1)){target[part]??={};target=target[part];}target[bits.at(-1)]=value;}if(e.target.dataset.color){$(`[data-field="${key}"]`).value=value;}if(/^#[0-9a-fA-F]{6}$/.test(value)){const picker=$(`[data-color="${key}"]`);if(picker)picker.value=value;}setDirty();});
 function notify(message){$('#adminToast').textContent=message;$('#adminToast').classList.add('visible');setTimeout(()=>$('#adminToast').classList.remove('visible'),3500);}
 window.MGTU_notify=notify;
 $('#saveDraft').addEventListener('click',async()=>{if(!$('#editorPanel').querySelector(':invalid')?.reportValidity()&&$('#editorPanel').querySelector(':invalid'))return;const blockError=MGTU_validateBlockSettings(draft);if(blockError)return notify(blockError);if(!draft.title.trim())return notify('Добавьте заголовок.');for(const key of ['accent','secondary','background'])if(!/^#[0-9a-fA-F]{6}$/.test(draft[key]))return notify('Укажите цвета в формате #RRGGBB.');for(const p of Object.values(draft.programs)){for(const key of ['document','cost'])if(p[key]&&!/^https?:\/\//i.test(p[key]))return notify('Ссылки программ должны начинаться с https:// или http://.');}if(draft.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email))return notify('Проверьте адрес электронной почты.');const button=$('#saveDraft');button.disabled=true;try{const result=await MGTU_api('/api/content',{method:'PUT',body:JSON.stringify({content:draft,revision:MGTU_contentRevision})});MGTU_setPublished(result);draft=structuredClone(MGTU_content());setDirty(false);MGTU_editor.saved();notify('Изменения сохранены на сайте и видны всем посетителям.');}catch(error){notify(error.message);}finally{button.disabled=false;}});
 $('#resetDraft').addEventListener('click',()=>{draft=structuredClone(MGTU_content());setDirty(false);render();MGTU_editor.preview();notify('Несохранённые изменения отменены.');});
 $('#editorPanel').addEventListener('click',e=>{const button=e.target.closest('[data-palette]');if(!button||!isAdmin())return;const palette=MGTU_PALETTES[button.dataset.palette];if(!palette)return;draft.background=palette.colors[0];draft.accent=button.dataset.palette==='brand'?'#f7f7f7':palette.colors[Math.min(3,palette.colors.length-1)];draft.secondary=button.dataset.palette==='brand'?'#a7c7ff':palette.colors[palette.colors.length-1];draft.brandVersion=2;setDirty();render();notify('Палитра выбрана. Сохраните изменения для предпросмотра.');});
 $$('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(!isAdmin()&&['design','users'].includes(b.dataset.view))return;view=b.dataset.view;render();}));
 function resizePreview(){$$('[data-preview]').forEach(b=>b.classList.toggle('active',b.dataset.preview===previewMode));const viewport=$('#previewViewport');const iframe=$('#sitePreview');const width=viewport.clientWidth;const source=previewMode==='mobile'?390:1280;const scale=Math.min(width/source,1);viewport.classList.toggle('mobile',previewMode==='mobile');iframe.style.width=source+'px';iframe.style.transform=`scale(${scale})`;iframe.style.height=Math.ceil(viewport.clientHeight/scale)+'px';}
 $$('[data-preview]').forEach(b=>b.addEventListener('click',()=>{previewMode=b.dataset.preview;$$('[data-preview]').forEach(x=>x.classList.toggle('active',x===b));$('#previewViewport').classList.toggle('mobile',previewMode==='mobile');resizePreview();}));
 new ResizeObserver(resizePreview).observe($('#previewViewport'));window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 MGTU_editor.init({getDraft:()=>draft,getPrograms:()=>data.programs,dirty:setDirty,render,renderPage:()=>{if(view==='page')$('#editorPanel').innerHTML=MGTU_editor.render();},openPage:()=>{view='page';render();window.scrollTo({top:Math.max(0,$('#editorPanel').getBoundingClientRect().top+window.scrollY-100),behavior:'instant'});},openProgram:id=>{view='programs';render();const original=data.programs.find(p=>p.id===id);if(original){$('#adminSearch').value=original.name;renderProgramList(original.name);const row=$(`[data-editor-program="${id}"]`);if(row)row.open=true;}}});
 fetch('data.json').then(r=>r.text()).then(text=>{data=JSON.parse(text.replace(/^\uFEFF/,''));$('#adminProgramCount').textContent=data.programs.length;render();}).catch(()=>{render();notify('Не удалось загрузить каталог. Перезагрузите страницу.');});render();resizePreview();
})();
